/**
 * Deletes every tag of a workspace that is on no response, and returns how many it removed.
 *
 * "Unused" is judged on the junction table itself, not on the visibility-filtered count the list shows:
 * a tag that only sits on responses the caller cannot read is still in use and must survive. One
 * `deleteMany` keeps the check and the delete in a single statement, so a tag applied meanwhile is not
 * removed by a stale read.
 */
export const deleteUnusedTagsByWorkspaceId = async (
  workspaceId: string
): Promise<Result<{ deletedCount: number }, { code: TagError; message: string }>> => {
  validateInputs([workspaceId, ZId]);

  try {
    const { count } = await prisma.tag.deleteMany({
      where: { workspaceId, responses: { none: {} } },
    });

    return ok({ deletedCount: count });
  } catch (error) {
    return err({
      code: TagError.UNEXPECTED_ERROR,
      message: error instanceof Error ? error.message : "Unknown error occurred",
    });
  }
};
EOF
